            return False
        if '/' in doc_id or '..' in doc_id:
            return False
        return True

    def create(self, doc_id, body):
        if not self._validate_id(doc_id):
            return 400
        if doc_id in self.documents:
            return 409
        self.documents[doc_id] = {'body': body, 'archived': False}
        return 201

    def read(self, doc_id):
        if not self._validate_id(doc_id):
            return (400, None)
        if doc_id not in self.documents:
            return (404, None)
        doc = self.documents[doc_id]
        return (200, doc['body'])

    def put(self, doc_id, body):
        if not self._validate_id(doc_id):
            return 400
        if doc_id not in self.documents:
            return 404
        self.documents[doc_id]['body'] = body
        self.documents[doc_id]['archived'] = False
        return 200

    def archive(self, doc_id):
        if not self._validate_id(doc_id):
            return 400
        if doc_id not in self.documents:
            return 404
        self.documents[doc_id]['archived'] = True
        return 200

    def list(self):
        return sorted([doc_id for doc_id in self.documents.keys()])
