class DocumentStore:
    """
    In-memory document store with create, read, put, archive, and list operations.
    Identifiers must be strings without '/' or '..'.  Status codes are returned
    according to the design specification.
    """

    def __init__(self):
        # mapping: doc_id -> (body, archived_flag)
        self._store = {}

    def _is_valid_id(self, doc_id: object) -> bool:
        """Check that the identifier is a string without '/' or '..'."""
        return isinstance(doc_id, str) and '/' not in doc_id and '..' not in doc_id

    def create(self, doc_id, body) -> int:
        """Create a new document. Returns 201 (created), 409 (exists), or 400 (invalid id)."""
        if not self._is_valid_id(doc_id):
            return 400  # invalid_id
        if doc_id in self._store:
            return 409  # exists
        self._store[doc_id] = (body, False)
        return 201  # created

    def read(self, doc_id):
        """Read a document. Returns (status, body) where status is 200, 404, or 400."""
        if not self._is_valid_id(doc_id):
            return (400, None)  # invalid_id
        if doc_id not in self._store:
            return (404, None)  # missing
        body, _ = self._store[doc_id]
        return (200, body)  # found

    def put(self, doc_id, body) -> int:
        """Update an existing document. Returns 200, 404, or 400."""
        if not self._is_valid_id(doc_id):
            return 400  # invalid_id
        if doc_id not in self._store:
            return 404  # missing
        _, archived = self._store[doc_id]
        self._store[doc_id] = (body, archived)
        return 200  # archived_put (same as 200)

    def archive(self, doc_id) -> int:
        """Archive an existing document. Returns 200, 404, or 400."""
        if not self._is_valid_id(doc_id):
            return 400  # invalid_id
        if doc_id not in self._store:
            return 404  # missing
        body, _ = self._store[doc_id]
        self._store[doc_id] = (body, True)
        return 200  # archived

    def list(self):
        """Return a sorted list of all document identifiers, archived or not."""
        return sorted(self._store.keys())
