        """
        Create a new document.
        Returns 201 if created, 409 if id already exists, 400 if id type invalid.
        """
        if not self._validate_id(doc_id):
            return 400  # invalid_id
        if doc_id in self._store:
            return 409  # exists
        self._store[doc_id] = {'body': body, 'archived': False}
        return 201  # created

    def read(self, doc_id):
        """
        Read a document.
        Returns (200, body) if found, (404, None) if missing, (400, None) if id invalid.
        """
        if not self._validate_id(doc_id):
            return 400, None  # invalid_id
        entry = self._store.get(doc_id)
        if entry is None:
            return 404, None  # missing
        return 200, entry['body']  # read

    def put(self, doc_id, body):
        """
        Update an existing document (even if archived).
        Returns 200 if updated, 404 if missing, 400 if id invalid.
        """
        if not self._validate_id(doc_id):
            return 400  # invalid_id
        entry = self._store.get(doc_id)
        if entry is None:
            return 404  # missing
        entry['body'] = body
        return 200  # archived_put / put

    def archive(self, doc_id):
        """
        Archive a document.
        Returns 200 if archived, 404 if missing, 400 if id invalid.
        """
        if not self._validate_id(doc_id):
            return 400  # invalid_id
        entry = self._store.get(doc_id)
        if entry is None:
            return 404  # missing
        entry['archived'] = True
        return 200  # archived

    def list(self):
        """
        Return a sorted list of all document identifiers (including archived ones).
        """
        return sorted(self._store.keys())
