class DocumentStore:
    """
    In‑memory document store that follows the invoices service design.

    All identifiers must be strings that do not contain '/' or '..'.
    Operations return the status codes defined in the design.
    """

    # Status codes
    _CREATED = 201
    _EXISTS = 409
    _INVALID_ID = 400
    _MISSING = 404
    _OK = 200
    _ARCHIVED_PUT = 409

    def __init__(self):
        # mapping: doc_id -> (body, archived_flag)
        self._store = {}

    # ---------- Helper methods ----------
    @staticmethod
    def _is_valid_id(doc_id):
        """
        Validate that the identifier is a string and does not contain
        '/' or '..'.
        """
        if not isinstance(doc_id, str):
            return False
        if '/' in doc_id or '..' in doc_id:
            return False
        return True

    # ---------- Core operations ----------
    def create(self, doc_id, body):
        """
        Create a new document. Returns status code.
        """
        if not self._is_valid_id(doc_id):
            return self._INVALID_ID
        if doc_id in self._store:
            return self._EXISTS
        self._store[doc_id] = (body, False)
        return self._CREATED

    def read(self, doc_id):
        """
        Read a document. Returns (status, body or None).
        """
        if not self._is_valid_id(doc_id):
            return (self._INVALID_ID, None)
        entry = self._store.get(doc_id)
        if entry is None:
            return (self._MISSING, None)
        body, _ = entry
        return (self._OK, body)

    def put(self, doc_id, body):
        """
        Update an existing document. Returns status code.
        """
        if not self._is_valid_id(doc_id):
            return self._INVALID_ID
        entry = self._store.get(doc_id)
        if entry is None:
            return self._MISSING
        _, archived = entry
        if archived:
            return self._ARCHIVED_PUT
        self._store[doc_id] = (body, False)
        return self._OK

    def archive(self, doc_id):
        """
        Archive an existing document. Returns status code.
        """
        if not self._is_valid_id(doc_id):
            return self._INVALID_ID
        entry = self._store.get(doc_id)
        if entry is None:
            return self._MISSING
        body, _ = entry
        self._store[doc_id] = (body, True)
        return self._OK

    def list(self):
        """
        Return a sorted list of all identifiers (including archived).
        """
        return sorted(self._store.keys())
