        """Create a new document. Return 201 on success, 409 if id exists,
        400 if id type is invalid."""
        status = self._check_id(doc_id)
        if status is not None:
            return status
        if doc_id in self._store:
            return 409
        self._store[doc_id] = (body, False)
        return 201

