        status = self._check_id(doc_id)
        if status is not None:
            return (status, None)
        if doc_id not in self._store:
            return (404, None)
        body, _ = self._store[doc_id]
        return (200, body)

    def put(self, doc_id, body) -> int:
        """Replace body of an existing document. Return 200 on success,
        404 if missing, 409 if trying to overwrite an archived document,
        400 if id type is invalid."""
        status = self._check_id(doc_id)
        if status is not None:
            return status
        if doc_id not in self._store:
            return 404
        _, archived = self._store[doc_id]
        if archived:
