        if doc_id in self._store:
            return 409  # exists
        self._store[doc_id] = (body, False)
        return 201  # created

    def read(self, doc_id):
        """Read a document.
        Returns (status, body) where body is None if missing or invalid id.
        """
        status = self._check_id(doc_id)
        if status is not None:
            return (status, None)
        entry = self._store.get(doc_id)
        if entry is None:
            return (404, None)  # missing
        body, _ = entry
        return (200, body)

    def put(self, doc_id, body):
        """Update an existing document's body.
        Returns 200 if replaced, 404 if missing, 400 for invalid id.
        """
        status = self._check_id(doc_id)
        if status is not None:
            return status
        if doc_id not in self._store:
            return 404  # missing
        _, archived = self._store[doc_id]
        self._store[doc_id] = (body, archived)
        return 200

    def archive(self, doc_id):
        """Mark a document as archived.
        Returns 200 if archived, 404 if missing, 400 for invalid id.
        """
        status = self._check_id(doc_id)
        if status is not None:
            return status
        entry = self._store.get(doc_id)
        if entry is None:
            return 404  # missing
        body, _ = entry
        self._store[doc_id] = (body, True)
        return 200

    def list(self):
        """Return a sorted list of all document identifiers, including archived."""
        return sorted(self._store.keys())
