class DocumentStore:
    """
    In‑memory document store with create, read, put, archive and list operations.
    Identifiers must be strings that do not contain '/' or '..'.
    """

    # Status codes
    CODE_CREATED = 201
    CODE_OK = 200
    CODE_CONFLICT = 409
    CODE_BAD_REQUEST = 400
    CODE_NOT_FOUND = 404

    def __init__(self):
        # store maps id -> {'body': ..., 'archived': bool}
        self._store = {}

    # ------------------------------------------------------------------ utils
    @staticmethod
    def _is_valid_id(doc_id):
        """Validate that doc_id is a string without '/' or '..'."""
        if not isinstance(doc_id, str):
            return False
        if '/' in doc_id or '..' in doc_id:
            return False
        return True

    # ------------------------------------------------------------------ CRUD
    def create(self, doc_id, body):
        """
        Create a new document.
        Returns status code.
        """
        if not self._is_valid_id(doc_id):
            return self.CODE_BAD_REQUEST
        if doc_id in self._store:
            return self.CODE_CONFLICT
        self._store[doc_id] = {'body': body, 'archived': False}
        return self.CODE_CREATED

    def read(self, doc_id):
        """
        Read a document.
        Returns (status, body or None).
        """
        if not self._is_valid_id(doc_id):
            return (self.CODE_BAD_REQUEST, None)
        entry = self._store.get(doc_id)
        if entry is None:
            return (self.CODE_NOT_FOUND, None)
        return (self.CODE_OK, entry['body'])

    def put(self, doc_id, body):
        """
        Update an existing document's body.
        Returns status code.
        """
        if not self._is_valid_id(doc_id):
            return self.CODE_BAD_REQUEST
        entry = self._store.get(doc_id)
        if entry is None:
            return self.CODE_NOT_FOUND
        if entry['archived']:
            return self.CODE_CONFLICT
        entry['body'] = body
        return self.CODE_OK

    def archive(self, doc_id):
        """
        Archive an existing document.
        Returns status code.
        """
        if not self._is_valid_id(doc_id):
            return self.CODE_BAD_REQUEST
        entry = self._store.get(doc_id)
        if entry is None:
            return self.CODE_NOT_FOUND
        entry['archived'] = True
        return self.CODE_OK

    # ------------------------------------------------------------------ list
    def list(self):
        """
        Return a sorted list of all document identifiers (including archived).
        """
        return sorted(self._store.keys())
