    store = make()
    assert store.create("doc1", "body") == 201
    status, body = store.read("doc1")
    assert status == 200 and body == "body"


def test_duplicate_creation(make):
    store = make()
    assert store.create("doc1", "body1") == 201
    assert store.create("doc1", "body2") == 409


def test_missing_document(make):
    store = make()
    status, body = store.read("missing")
    assert status == 404 and body is None
    assert store.put("missing", "body") == 404


def test_archive_and_put(make):
    store = make()
    store.create("doc1", "body1")
    assert store.archive("doc1") == 200
    status, body = store.read("doc1")
    assert status == 200 and body == "body1"
    assert store.put("doc1", "newbody") == 200
    status, body = store.read("doc1")
    assert body == "newbody"


def test_list_sorted(make):
    store = make()
    store.create("b", "bodyb")
    store.create("a", "bodya")
    store.create("c", "bodyc")
    assert store.list() == ["a", "b", "c"]


def test_invalid_id(make):
    store = make()
    assert store.create(123, "body") == 400
    assert store.read(123)[0] == 400
    assert store.put(123, "body") == 400
    assert store.archive(123) == 400


def test_archived_listed(make):
    store = make()
    store.create("doc1", "body")
    store.archive("doc1")
    assert "doc1" in store.list()
