class DocumentStore:
    """
    In‑memory document store with create, read, put, archive and list operations.
    Status codes:
        201  - Created
        200  - OK (successful read, put, archive)
        404  - Not found
        409  - Conflict (duplicate create, put on archived)
        400  - Bad request (invalid id type)
    """
    def __init__(self):
        # internal mapping: id -> (body, archived_flag)
        self._store = {}

    def _validate_id(self, doc_id):
        if not isinstance(doc_id, str):
            return False
        return True

    def create(self, doc_id, body):
        """Create a new document. Returns status code."""
        if not self._validate_id(doc_id):
            return 400
        if doc_id in self._store:
            return 409
        self._store[doc_id] = (body, False)
        return 201

    def read(self, doc_id):
        """Read a document. Returns (status, body or None)."""
        if not self._validate_id(doc_id):
            return 400, None
        entry = self._store.get(doc_id)
        if entry is None:
            return 404, None
        body, _ = entry
        return 200, body

    def put(self, doc_id, body):
        """Replace the body of an existing document. Returns status code."""
        if not self._validate_id(doc_id):
            return 400
        entry = self._store.get(doc_id)
        if entry is None:
            return 404
        _, archived = entry
        if archived:
            return 409
        self._store[doc_id] = (body, False)
        return 200

    def archive(self, doc_id):
        """Mark a document as archived. Returns status code."""
        if not self._validate_id(doc_id):
            return 400
        entry = self._store.get(doc_id)
        if entry is None:
            return 404
        body, _ = entry
        self._store[doc_id] = (body, True)
        return 200

    def list(self):
        """Return a sorted list of all document identifiers."""
        return sorted(self._store.keys())
