class DocumentStore:
    """
    In‑memory document store implementing the invoices service API.

    Status codes (see design):
        - 201  (created)
        - 200  (OK, used for put and archive)
        - 409  (exists)
        - 404  (missing)
        - 400  (invalid_id)
    """

    # status code constants
    CREATED = 201
    OK = 200
    EXISTS = 409
    MISSING = 404
    INVALID_ID = 400

    def __init__(self):
        # mapping from doc_id -> (body, archived_flag)
        self._store = {}

    # ---- helper ----
    def _validate_id(self, doc_id):
        """Return False if doc_id is not a string, True otherwise."""
        return isinstance(doc_id, str)

    # ---- public API ----
    def create(self, doc_id, body):
        """Create a new document. Return status code."""
        if not self._validate_id(doc_id):
            return self.INVALID_ID
        if doc_id in self._store:
            return self.EXISTS
        self._store[doc_id] = (body, False)   # not archived
        return self.CREATED

    def read(self, doc_id):
        """Return (status, body) tuple."""
        if not self._validate_id(doc_id):
            return (self.INVALID_ID, None)
        if doc_id not in self._store:
            return (self.MISSING, None)
        body, _ = self._store[doc_id]
        return (self.OK, body)

    def put(self, doc_id, body):
        """Replace body of an existing document. Return status code."""
        if not self._validate_id(doc_id):
            return self.INVALID_ID
        if doc_id not in self._store:
            return self.MISSING
        _, archived = self._store[doc_id]
        self._store[doc_id] = (body, archived)   # keep archived flag
        return self.OK

    def archive(self, doc_id):
        """Mark a document as archived. Return status code."""
        if not self._validate_id(doc_id):
            return self.INVALID_ID
        if doc_id not in self._store:
            return self.MISSING
        body, _ = self._store[doc_id]
        self._store[doc_id] = (body, True)
        return self.OK

    def list(self):
        """Return a sorted list of all document identifiers."""
        return sorted(self._store.keys())
