from typing import Dict, Tuple, List, Optional

class DocumentStore:
    """
    In‑memory document store that supports create, read, put, archive and list operations.
    All operations validate that the document identifier is a string; otherwise a 400 status
    code is returned.  Status codes are defined by the service design.
    """
    # Status codes from the design
    STATUS_CREATED        = 201
    STATUS_CONFLICT       = 409   # used for both "exists" and "archived_put"
    STATUS_INVALID_ID     = 400
    STATUS_NOT_FOUND      = 404
    STATUS_OK             = 200

    def __init__(self) -> None:
        # Store mapping: id -> {'body': str, 'archived': bool}
        self._store: Dict[str, Dict[str, object]] = {}

    # -------------------------------------------------------------------------
    # Helper
    # -------------------------------------------------------------------------
    def _validate_id(self, doc_id) -> bool:
        """Return True if doc_id is a string, else False."""
        return isinstance(doc_id, str)

    # -------------------------------------------------------------------------
    # Public API
    # -------------------------------------------------------------------------
    def create(self, doc_id: str, body: str) -> int:
        """Create a new document. 201 if created, 409 if id already exists, 400 if id type invalid."""
        if not self._validate_id(doc_id):
            return self.STATUS_INVALID_ID
        if doc_id in self._store:
            return self.STATUS_CONFLICT
        self._store[doc_id] = {'body': body, 'archived': False}
        return self.STATUS_CREATED

    def read(self, doc_id: str) -> Tuple[int, Optional[str]]:
        """Read a document. 200 and body if found, 404 if missing, 400 if id type invalid."""
        if not self._validate_id(doc_id):
            return (self.STATUS_INVALID_ID, None)
        entry = self._store.get(doc_id)
        if entry is None:
            return (self.STATUS_NOT_FOUND, None)
        return (self.STATUS_OK, entry['body'])

    def put(self, doc_id: str, body: str) -> int:
        """
        Update an existing document's body.
        200 if updated, 404 if missing, 409 if archived, 400 if id type invalid.
        """
        if not self._validate_id(doc_id):
            return self.STATUS_INVALID_ID
        entry = self._store.get(doc_id)
        if entry is None:
            return self.STATUS_NOT_FOUND
        if entry['archived']:
            return self.STATUS_CONFLICT
        entry['body'] = body
        return self.STATUS_OK

    def archive(self, doc_id: str) -> int:
        """
        Archive a document. 200 if archived (or already archived), 404 if missing,
        400 if id type invalid.
        """
        if not self._validate_id(doc_id):
            return self.STATUS_INVALID_ID
        entry = self._store.get(doc_id)
        if entry is None:
            return self.STATUS_NOT_FOUND
        entry['archived'] = True
        return self.STATUS_OK

    def list(self) -> List[str]:
        """Return a sorted list of all document identifiers (archived included)."""
        return sorted(self._store.keys())
