class DocumentStore:
    """
    In‑memory document store that supports create, read, put, archive, and list operations.
    All identifiers must be of type str; otherwise a status 400 (invalid_id) is returned.
    """
    def __init__(self):
        # Store documents as {doc_id: {"body": ..., "archived": bool}}
        self._store = {}

    # Helper to validate identifier type
    def _validate_id(self, doc_id):
        if not isinstance(doc_id, str):
            return False
        return True

    def create(self, doc_id, body):
        """Create a new document. Returns status 201 or 409 if already exists, 400 if id invalid."""
        if not self._validate_id(doc_id):
            return 400  # invalid_id
        if doc_id in self._store:
            return 409  # exists
        self._store[doc_id] = {"body": body, "archived": False}
        return 201  # created

    def read(self, doc_id):
        """Return (status, body). 200 and body if present, 404 if missing, 400 if id invalid."""
        if not self._validate_id(doc_id):
            return 400, None  # invalid_id
        doc = self._store.get(doc_id)
        if doc is None:
            return 404, None  # missing
        return 200, doc["body"]  # status 200

    def put(self, doc_id, body):
        """Replace body of existing document. 200 on success, 404 if missing, 409 if archived, 400 if id invalid."""
        if not self._validate_id(doc_id):
            return 400  # invalid_id
