        if not self._is_valid_id(doc_id):
            return 400, None  # invalid_id
        if doc_id not in self._store:
            return 404, None  # missing
        return 200, self._store[doc_id]["body"]

    def put(self, doc_id: object, body: object) -> int:
        if not self._is_valid_id(doc_id):
            return 400  # invalid_id
        if doc_id not in self._store:
            return 404  # missing
        if self._store[doc_id]["archived"]:
            return 409  # archived_put
        self._store[doc_id]["body"] = body
