    In‑memory document store with create, read, put, archive and list operations.
    """

    def __init__(self):
        self._store = {}          # doc_id -> body
        self._archived = set()    # set of archived doc_ids

    def _is_valid_id(self, doc_id):
        """Return True if doc_id is a valid string identifier."""
        if not isinstance(doc_id, str):
            return False
        # SEC-1: disallow path traversal
        if '/' in doc_id or '..' in doc_id:
            return False
        return True

    def create(self, doc_id, body):
        """Create a new document. 201 on success, 409 if id exists, 400 if id invalid."""
        if not self._is_valid_id(doc_id):
            return 400
        if doc_id in self._store:
            return 409
        self._store[doc_id] = body
        self._archived.discard(doc_id)
        return 201

    def read(self, doc_id):
        """
        Read a document.
        Returns a tuple (status, body). 200 and body if found,
        404 if missing, 400 if id invalid.
        """
        if not self._is_valid_id(doc_id):
            return 400, None
        if doc_id in self._store:
            return 200, self._store[doc_id]
        return 404, None

    def put(self, doc_id, body):
        """
        Update an existing document. 200 on success,
        404 if missing, 400 if id invalid.
        """
        if not self._is_valid_id(doc_id):
            return 400
        if doc_id in self._store:
            self._store[doc_id] = body
            return 200
        return 404

    def archive(self, doc_id):
        """
        Archive a document. 200 on success, 404 if missing,
        400 if id invalid. Archived docs remain readable and listed.
        """
        if not self._is_valid_id(doc_id):
            return 400
        if doc_id in self._store:
            self._archived.add(doc_id)
            return 200
        return 404

    def list(self):
        """Return a sorted list of all document identifiers, including archived ones."""
        return sorted(self._store.keys())
