    assert status == 200
    status, body = store.read('doc2')
    assert status == 200 and body == 'new'
    status = store.put('doc2', 'another')
    assert status == 409
    status, body = store.read('doc2')
    assert body == 'new'
    status = store.put('missing', 'x')
    assert status == 404

def test_list_and_invalid_id(make):
    store = make()
    store.create('b', 'b')
    store.create('a', 'a')
    store.create('c', 'c')
    l = store.list()
    assert l == ['a', 'b', 'c']
    store.archive('b')
    l = store.list()
    assert l == ['a', 'b', 'c']
    status = store.create(123, 'num')
    assert status == 400
    status, body = store.read(None)
    assert status == 400 and body is None
    status = store.put(3.14, 'float')
    assert status == 400
    status = store.archive([])
    assert status == 400
    status = store.archive('missing')
    assert status == 404
