class DocumentStore:
    """
    In‑memory document store supporting create, read, put, archive, and list operations.
    All identifiers must be strings; otherwise operations return status 400.
    Status codes:
        201 - Created
        200 - OK
        404 - Not Found
        409 - Conflict (existing document or attempt to overwrite archived)
        400 - Invalid ID
    """

    def __init__(self):
        # Internal storage: id -> {'body': ..., 'archived': bool}
        self._store = {}

    def _validate_id(self, doc_id):
        """Return True if doc_id is a string, else False."""
        return isinstance(doc_id, str)

    def create(self, doc_id, body):
        """Create a new document. 201 if created, 409 if already exists, 400 if id invalid."""
        if not self._validate_id(doc_id):
            return 400
        if doc_id in self._store:
            return 409
        self._store[doc_id] = {'body': body, 'archived': False}
        return 201

    def read(self, doc_id):
        """Read a document. 200 and body if present, 404 if missing, 400 if id invalid."""
        if not self._validate_id(doc_id):
            return 400, None
        entry = self._store.get(doc_id)
        if entry is None:
            return 404, None
        return 200, entry['body']

    def put(self, doc_id, body):
        """Replace body of existing document. 200 if replaced, 404 if missing,
        409 if document is archived, 400 if id invalid."""
        if not self._validate_id(doc_id):
            return 400
        entry = self._store.get(doc_id)
        if entry is None:
            return 404
        if entry['archived']:
            return 409
        entry['body'] = body
        return 200

    def archive(self, doc_id):
        """Archive an existing document. 200 if archived, 404 if missing,
        400 if id invalid."""
        if not self._validate_id(doc_id):
            return 400
        entry = self._store.get(doc_id)
        if entry is None:
            return 404
        entry['archived'] = True
        return 200

    def list(self):
        """Return a sorted list of all document identifiers, including archived ones."""
        return sorted(self._store.keys())
