class DocumentStore:
    """In‑memory document store implementing the contract service."""

    # Status codes defined by the contract
    _CREATED = 201
    _EXISTS = 409
    _INVALID_ID = 400
    _MISSING = 404
    _OK = 200
    _ARCHIVED_PUT = 409

    def __init__(self):
        # store maps doc_id -> {"body": body, "archived": bool}
        self._store = {}

    # ---------- Helper ----------
    @staticmethod
    def _is_valid_id(doc_id):
        """Check if the identifier is of the correct type (string)."""
        return isinstance(doc_id, str)

    # ---------- Public API ----------
    def create(self, doc_id, body):
        """Create a new document. Return status code."""
        if not self._is_valid_id(doc_id):
            return self._INVALID_ID
        if doc_id in self._store:
            return self._EXISTS
        self._store[doc_id] = {"body": body, "archived": False}
        return self._CREATED

    def read(self, doc_id):
        """Read a document. Return (status, body) tuple."""
        if not self._is_valid_id(doc_id):
            return (self._INVALID_ID, None)
        entry = self._store.get(doc_id)
        if entry is None:
            return (self._MISSING, None)
        return (self._OK, entry["body"])

    def put(self, doc_id, body):
        """Replace an existing document. Return status code."""
        if not self._is_valid_id(doc_id):
            return self._INVALID_ID
        entry = self._store.get(doc_id)
        if entry is None:
            return self._MISSING
        if entry["archived"]:
            return self._ARCHIVED_PUT
        entry["body"] = body
        return self._OK

    def archive(self, doc_id):
        """Archive a document. Return status code."""
        if not self._is_valid_id(doc_id):
            return self._INVALID_ID
        entry = self._store.get(doc_id)
        if entry is None:
            return self._MISSING
        entry["archived"] = True
        return self._OK

    def list(self):
        """Return a sorted list of all document identifiers."""
        return sorted(self._store.keys())
