class DocumentStore:
    """
    In‑memory document store with the following operations:

    * create(doc_id, body) -> int
        - 201: document created
        - 409: document with same id already exists
        - 400: id is not a string

    * read(doc_id) -> tuple[int, str | None]
        - 200, body: document found
        - 404, None: document not found
        - 400, None: id is not a string

    * put(doc_id, body) -> int
        - 200: document replaced
        - 404: document not found
        - 409: cannot overwrite an archived document
        - 400: id is not a string

    * archive(doc_id) -> int
        - 200: document archived (idempotent)
        - 404: document not found
        - 400: id is not a string

    * list() -> list[str]
        - returns all identifiers (archived or not) in sorted order
    """

    def __init__(self) -> None:
        # mapping: doc_id -> (body, archived_flag)
        self._store: dict[str, tuple[str, bool]] = {}

    @staticmethod
    def _validate_id(doc_id: object) -> bool:
        return isinstance(doc_id, str)

    def create(self, doc_id: object, body: str) -> int:
        if not self._validate_id(doc_id):
            return 400  # invalid_id
        if doc_id in self._store:
            return 409  # exists
        self._store[doc_id] = (body, False)
        return 201  # created

    def read(self, doc_id: object) -> tuple[int, str | None]:
        if not self._validate_id(doc_id):
            return 400, None  # invalid_id
        if doc_id not in self._store:
            return 404, None  # missing
        body, _ = self._store[doc_id]
        return 200, body

    def put(self, doc_id: object, body: str) -> int:
        if not self._validate_id(doc_id):
            return 400  # invalid_id
        if doc_id not in self._store:
            return 404  # missing
        _, archived = self._store[doc_id]
        if archived:
            return 409  # archived_put
        self._store[doc_id] = (body, False)
        return 200  # success

    def archive(self, doc_id: object) -> int:
        if not self._validate_id(doc_id):
            return 400  # invalid_id
        if doc_id not in self._store:
            return 404  # missing
        body, _ = self._store[doc_id]
        self._store[doc_id] = (body, True)
        return 200  # archived

    def list(self) -> list[str]:
        return sorted(self._store.keys())
